import React, { useState, useEffect } from 'react';
import {
  TextField, Button, Container, Typography, Paper, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Chip, Box, Alert,
  CssBaseline, useMediaQuery, Zoom, Grid, ThemeProvider, createTheme, Fade,
} from '@mui/material';
import { blue, green, red, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: {
      main: blue[900],
    },
    secondary: {
      main: green[700],
    },
    background: {
      default: '#f5f7fa',
      paper: '#ffffff',
    },
    error: {
      main: red[700],
    },
    text: {
      primary: '#1a1a1a',
      secondary: '#555555',
    },
  },
  typography: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    h3: {
      fontWeight: 700,
      letterSpacing: '0.05em',
      color: blue[900],
    },
    h6: {
      fontWeight: 600,
      color: '#444',
    },
    button: {
      textTransform: 'none',
      fontWeight: 700,
      borderRadius: 12,
      padding: '14px 28px',
      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
    },
  },
  shape: {
    borderRadius: 12,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          transition: 'all 0.3s ease',
          '&:hover': {
            boxShadow: '0 8px 24px rgba(0,0,0,0.2)',
            backgroundColor: blue[800],
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          boxShadow: '0 16px 48px rgba(0,0,0,0.12)',
          padding: '32px',
          borderRadius: 12,
          backgroundColor: '#fff',
        },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        root: {
          fontSize: 16,
          padding: '16px 20px',
        },
        head: {
          backgroundColor: blue[900],
          color: '#fff',
          fontWeight: 700,
          fontSize: 16,
          letterSpacing: '0.08em',
          position: 'sticky',
          top: 0,
          zIndex: 3,
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);
  const [lastChecked, setLastChecked] = useState(null);

  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://127.0.0.1:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
        setMonitoringStatus('Monitoring');
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  const stopMonitoring = async () => {
    try {
      const response = await fetch('http://127.0.0.1:5001/stop_monitoring', { method: 'POST' });
      if (response.ok) {
        setMonitoringStatus('Idle');
        setThreatDetected(false);
        setThreatLogs([]);
        setMessage('Monitoring stopped.');
        setLastChecked(null);
      } else {
        setMessage('Failed to stop monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    setThreatLogs([]);

    let interval = null;

    if (monitoringStatus === 'Monitoring') {
      interval = setInterval(async () => {
        try {
          const response = await fetch('http://127.0.0.1:5001/status');
          const data = await response.json();
          setMonitoringStatus(data.status);
          setThreatDetected(data.threat_detected);
          setLastChecked(new Date().toLocaleTimeString());

          const logsResponse = await fetch('http://127.0.0.1:5001/threat_logs');
          const logsData = await logsResponse.json();
          const cleanedLogs = logsData.map(log => {
            let cleanedWebsite = log.website;
            if (cleanedWebsite.startsWith('http://')) {
              cleanedWebsite = cleanedWebsite.slice(7);
            } else if (cleanedWebsite.startsWith('https://')) {
              cleanedWebsite = cleanedWebsite.slice(8);
            }
            return { ...log, website: cleanedWebsite };
          });
          setThreatLogs(cleanedLogs);
        } catch (error) {
          setMonitoringStatus('Error');
          setThreatDetected(false);
          setThreatLogs([]);
          setLastChecked(null);
        }
      }, 5000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [monitoringStatus]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring':
        return 'primary';
      case 'Idle':
        return 'default';
      case 'Starting':
        return 'secondary';
      default:
        return 'default';
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Container maxWidth="lg" sx={{ mt: 5, mb: 5, pl: '2cm' }}>
        <Typography variant={isMobile ? 'h5' : 'h3'} align="center" sx={{ fontWeight: 'bold', mb: 4 }}>
          Cyber Threat Detection System
        </Typography>
        <Typography variant="h6" align="center" sx={{ mb: 2, color: grey[700] }}>
          Real-time Website Cyber Threat Monitoring and Detection
        </Typography>
        <Box sx={{ textAlign: 'center', mb: 3 }}>
          <Typography variant="body1" color="text.secondary">
            {lastChecked ? `Last checked at: ${lastChecked}` : 'Monitoring not started'}
          </Typography>
        </Box>
        <Grid container spacing={4}>
          <Grid item xs={12} md={5}>
            <Paper elevation={6} sx={{ p: 4, height: 340, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
              <Box
                component="form"
                onSubmit={(e) => {
                  e.preventDefault();
                  startMonitoring();
                }}
                sx={{
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 3,
                }}
              >
                <TextField
                  label="Website URL"
                  variant="outlined"
                  fullWidth
                  value={website}
                  onChange={(e) => setWebsite(e.target.value)}
                  required
                  sx={{ fontSize: 16 }}
                />
                <Box sx={{ display: 'flex', gap: 3, mt: 2 }}>
                  <Button variant="contained" color="primary" type="submit" fullWidth sx={{ py: 2, fontSize: 16 }}>
                    Start Monitoring
                  </Button>
                  <Button variant="outlined" color="error" fullWidth sx={{ py: 2, fontSize: 16 }} onClick={stopMonitoring}>
                    Stop Monitoring
                  </Button>
                </Box>
              </Box>
              {message && (
                <Zoom in={Boolean(message)}>
                  <Alert severity="info" sx={{ mt: 4, borderRadius: 4, fontWeight: 600, fontSize: 16 }}>
                    {message}
                  </Alert>
                </Zoom>
              )}
              <Box sx={{ mt: 6, textAlign: 'center' }}>
                <Typography variant="h6" component="span" sx={{ fontWeight: 600 }}>
                  Status:
                </Typography>
                <Chip
                  label={monitoringStatus}
                  color={threatDetected ? 'error' : getStatusColor(monitoringStatus)}
                  sx={{
                    ml: 2,
                    fontWeight: 700,
                    fontSize: 18,
                    px: 4,
                    py: 1,
                    borderRadius: 10,
                    boxShadow: '0 6px 20px rgba(0,0,0,0.15)',
                    transition: 'background-color 0.5s ease',
                  }}
                />
                {threatDetected && (
                  <Fade in={threatDetected} timeout={700}>
                    <Alert
                      severity="error"
                      sx={{
                        mt: 4,
                        borderRadius: 10,
                        fontWeight: 700,
                        fontSize: 18,
                        boxShadow: '0 8px 28px rgba(211,47,47,0.8)',
                        transition: 'all 0.5s ease',
                      }}
                    >
                      Threat Detected on the website!
                    </Alert>
                  </Fade>
                )}
              </Box>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Paper elevation={6} sx={{ p: 5, borderRadius: 12, boxShadow: '0 12px 36px rgba(0,0,0,0.15)', maxHeight: 520, overflowY: 'auto', width: '100%' }}>
              <Typography variant="h5" gutterBottom sx={{ fontWeight: 700, mb: 5, color: blue[900], position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 3 }}>
                Threat Detection Log
              </Typography>
              <TableContainer sx={{ maxHeight: 460 }}>
                <Table stickyHeader aria-label="threat detection log table" sx={{ minWidth: 900 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell sx={{ fontWeight: 700, position: 'sticky', top: 0, backgroundColor: blue[900], color: '#fff', zIndex: 4 }}>Timestamp</TableCell>
                      <TableCell sx={{ fontWeight: 700, position: 'sticky', top: 0, backgroundColor: blue[900], color: '#fff', zIndex: 4 }}>Website</TableCell>
                      <TableCell sx={{ fontWeight: 700, position: 'sticky', top: 0, backgroundColor: blue[900], color: '#fff', zIndex: 4 }}>Threat Name</TableCell>
                      <TableCell sx={{ fontWeight: 700, position: 'sticky', top: 0, backgroundColor: blue[900], color: '#fff', zIndex: 4 }}>Message</TableCell>
                      <TableCell sx={{ fontWeight: 700, position: 'sticky', top: 0, backgroundColor: blue[900], color: '#fff', zIndex: 4 }}>Solution</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {threatLogs.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={5} align="center" sx={{ fontStyle: 'italic', fontSize: 16 }}>
                          No threats detected yet.
                        </TableCell>
                      </TableRow>
                    ) : (
                      threatLogs.map((log) => (
                        <TableRow key={log.id} hover sx={{ '&:hover': { backgroundColor: grey[100] } }}>
                          <TableCell>{log.timestamp}</TableCell>
                          <TableCell>{log.website}</TableCell>
                          <TableCell>{log.threat_name}</TableCell>
                          <TableCell>{log.message}</TableCell>
                          <TableCell>{log.solution}</TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>
        </Grid>
      </Container>
    </ThemeProvider>
  );
}

export default App;
